package admin

const environmentStyles = `.section-head .button{white-space:nowrap;text-decoration:none}.data-row a{color:var(--teal);font-weight:750;text-decoration:none}.data-row a:hover,.back-link:hover{text-decoration:underline}.search-field{max-width:500px;margin:0 0 20px}.back-link{display:inline-block;color:var(--teal);font-weight:700;text-decoration:none;margin-bottom:12px}.actions a.button{text-decoration:none}.detail-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:20px 0 28px}.detail-field{display:grid;gap:5px;overflow-wrap:anywhere}.detail-field span{color:var(--muted);font-size:12px}.detail-field strong{color:var(--ink);font-size:15px;font-weight:650}.repository-detail{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;border:1px solid var(--line);border-radius:7px;padding:16px}@media(max-width:650px){.detail-grid,.repository-detail{grid-template-columns:1fr}.section-head{align-items:start;flex-wrap:wrap}}`

const groupPanel = `<section class="section" id="groups-section"><h2>Environment groups</h2><p class="section-desc">Organize deployment environments under a platform group.</p><form id="group-form"><div class="grid two"><label class="field">Group code<input name="code" required placeholder="raptor"></label><label class="field">Group name<input name="name" required placeholder="Raptor"></label></div><div class="actions"><button class="button">Create group</button></div></form><h3>Groups</h3><div id="group-list" class="data-list" aria-live="polite"></div></section>`

const environmentListPanel = `<section class="section" id="environments-section"><div class="section-head"><div><h2>Configured environments</h2><p class="section-desc">Select an environment to view its details.</p></div><a class="button" href="/environments?mode=create">Create environment</a></div><label class="field search-field">Search environments<input id="environment-search" type="search" placeholder="Search by code, group, stage, cloud or region" autocomplete="off"></label><div id="environment-list" class="data-list" aria-live="polite"></div></section>`

const environmentDetailPanel = `<section class="section" id="environment-detail"><div class="section-head"><div><a class="back-link" href="/environments">Environments</a><h2 id="detail-code">Environment</h2></div><a class="button" id="edit-environment" href="#">Edit</a></div><div id="environment-fields" class="detail-grid"></div><h3>Repositories</h3><div id="detail-repositories" class="data-list"></div></section>`

const environmentFormPanel = `<section class="section" id="environments-section"><a class="back-link" id="form-back" href="/environments">Environments</a><h2 id="form-heading">Create environment</h2><p class="section-desc">Set the cloud target and its source repositories.</p><form id="env-form"><div class="grid"><label class="field">Code<input name="code" required></label><label class="field">Group code<input name="groupCode" required></label><label class="field">Stage<input name="stage" required></label><label class="field">Cloud<input name="cloud"></label><label class="field">Region<input name="region"></label><label class="field">Cloud account ID<input name="accountId"></label><label class="field">ACK cluster ID<input name="ackClusterId"></label></div><h3>Repositories</h3><p class="section-desc">All configured repositories are attached to each sandbox attempt. Rows using the same repository URL must use the same base branch.</p><div id="repository-rows" class="repo-rows"></div><div class="actions"><button class="button secondary" type="button" id="add-repository">Add repository</button></div><div class="actions"><button class="button" id="save-environment">Create environment</button><a class="button secondary" id="cancel-environment" href="/environments">Cancel</a></div></form></section>`

const environmentScript = `<script>
let environments=[];
function environmentCode(){const parts=location.pathname.split('/');return parts.length>2?decodeURIComponent(parts[2]):''}
function environmentURL(code){return '/environments/'+encodeURIComponent(code)}
function renderRows(id,items,kind){const root=document.getElementById(id);root.replaceChildren();if(!items.length){const p=document.createElement('p');p.className='empty';p.textContent=kind==='environments'&&document.getElementById('environment-search').value.trim()?'No matching environments.':'No '+kind+' yet.';root.append(p);return}for(const item of items){const row=document.createElement('div');row.className='data-row';const code=document.createElement(kind==='environments'?'a':'strong');code.textContent=item.code||'Unnamed';if(kind==='environments')code.href=environmentURL(item.code);const detail=document.createElement('span');detail.textContent=kind==='groups'?(item.name||''):[item.groupCode,item.stage,item.cloud,item.region].filter(Boolean).join(' / ');row.append(code,detail);root.append(row)}}
async function refreshEnvironments(){if(document.getElementById('group-list'))renderRows('group-list',await api('environment-groups'),'groups');if(document.getElementById('environment-list')){environments=await api('environments');filterEnvironments()}}
function filterEnvironments(){const search=document.getElementById('environment-search');if(!search)return;const query=search.value.trim().toLocaleLowerCase();const matches=environments.filter(env=>[env.code,env.groupCode,env.stage,env.cloud,env.region].some(value=>String(value||'').toLocaleLowerCase().includes(query)));renderRows('environment-list',matches,'environments')}
if(document.getElementById('environment-search'))document.getElementById('environment-search').oninput=filterEnvironments;
if(document.getElementById('group-form'))document.getElementById('group-form').onsubmit=safely(async e=>{await api('environment-groups','POST',Object.fromEntries(new FormData(e.target)));e.target.reset();await refreshEnvironments();document.getElementById('notice').textContent='Group created.'});
function detailField(root,label,value){const item=document.createElement('div');item.className='detail-field';const name=document.createElement('span');name.textContent=label;const text=document.createElement('strong');text.textContent=value||'—';item.append(name,text);root.append(item)}
async function loadEnvironmentDetail(){const env=await api('environments/'+encodeURIComponent(environmentCode()));document.getElementById('detail-code').textContent=env.code;document.getElementById('edit-environment').href=environmentURL(env.code)+'/edit';const fields=document.getElementById('environment-fields');for(const [label,value] of [['Group code',env.groupCode],['Stage',env.stage],['Cloud',env.cloud],['Region',env.region],['Cloud account ID',env.accountId],['ACK cluster ID',env.ackClusterId]])detailField(fields,label,value);const repos=document.getElementById('detail-repositories');for(const repo of env.repositories||[]){const card=document.createElement('div');card.className='repository-detail';detailField(card,'Purpose',repo.purpose);detailField(card,'HTTPS GitHub URL',repo.url);detailField(card,'Base branch',repo.baseBranch);detailField(card,'Directory',repo.directory);repos.append(card)}if(!repos.children.length){const empty=document.createElement('p');empty.className='empty';empty.textContent='No repositories configured.';repos.append(empty)}}
const envForm=document.getElementById('env-form');
const repoRows=document.getElementById('repository-rows');
function addRepository(repo={}){const row=document.createElement('fieldset');const branchRequired=!repo.url||!!repo.baseBranch;row.innerHTML='<legend>Repository</legend><label class="field">Purpose<select name="purpose"><option value="terraform">Terraform</option><option value="kubernetes">Kubernetes</option></select></label><label class="field">HTTPS GitHub URL<input name="url" type="url" required></label><label class="field">Base branch<input name="baseBranch"'+(branchRequired?' required':'')+'></label><label class="field">Directory<input name="directory" required></label><button class="button secondary" type="button">Remove repository</button>';row.querySelector('[name="purpose"]').value=repo.purpose||'terraform';for(const key of ['url','baseBranch','directory'])row.querySelector('[name="'+key+'"]').value=repo[key]||'';row.querySelector('button').onclick=()=>row.remove();repoRows.append(row)}
if(envForm)document.getElementById('add-repository').onclick=()=>addRepository();
async function loadEnvironmentForm(){const code=environmentCode();if(!code)return;const env=await api('environments/'+encodeURIComponent(code));document.getElementById('form-heading').textContent='Edit '+env.code;document.getElementById('save-environment').textContent='Save changes';document.getElementById('form-back').href=environmentURL(code);document.getElementById('cancel-environment').href=environmentURL(code);for(const key of ['code','groupCode','stage','cloud','region','accountId','ackClusterId'])envForm.elements[key].value=env[key]||'';envForm.elements.code.readOnly=true;for(const repo of env.repositories||[])addRepository(repo)}
if(envForm)envForm.onsubmit=safely(async e=>{const f=new FormData(e.target);const v={code:f.get('code'),groupCode:f.get('groupCode'),stage:f.get('stage'),cloud:f.get('cloud'),region:f.get('region'),accountId:f.get('accountId'),ackClusterId:f.get('ackClusterId'),repositories:[]};for(const row of repoRows.children){const field=name=>row.querySelector('[name="'+name+'"]').value.trim();v.repositories.push({purpose:field('purpose'),url:field('url'),baseBranch:field('baseBranch'),directory:field('directory')})}const code=environmentCode();await api('environments'+(code?'/'+encodeURIComponent(code):''),code?'PATCH':'POST',v);location.assign(environmentURL(v.code))});
async function refreshEnvironmentPage(){if(document.getElementById('environment-list')||document.getElementById('group-list'))await refreshEnvironments();if(document.getElementById('environment-detail'))await loadEnvironmentDetail();if(envForm)await loadEnvironmentForm()}
</script>`
